DROP TABLE IF EXISTS `dosage_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dosage_logs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `timestamp` varchar(50) DEFAULT NULL,
  `hn` varchar(20) DEFAULT NULL,
  `patient_name` varchar(255) DEFAULT NULL,
  `calculated_bsa` varchar(20) DEFAULT NULL,
  `formula_used` varchar(255) DEFAULT NULL,
  `prescribed_dose` varchar(50) DEFAULT NULL,
  `user_name` varchar(255) DEFAULT NULL,
  `gender` varchar(20) DEFAULT NULL,
  `age` varchar(20) DEFAULT NULL,
  `height` varchar(20) DEFAULT NULL,
  `weight` varchar(20) DEFAULT NULL,
  `ward` varchar(100) DEFAULT NULL,
  `allergies` text,
  `drugs_used` text,
  `doctor` varchar(255) DEFAULT NULL,
  `gfr_value` varchar(50) DEFAULT NULL,
  `other_lab` varchar(255) DEFAULT NULL,
  `dob` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=67 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
