INSERT INTO `drug_rules` VALUES (1,'PACLITAXEL','[\"NSS\"]','คำเตือนการให้ยา','ต้องผสมในขวดแก้วหรือขวดพลาสติกที่ปราศจากสาร Di(2-ethylhexyl) phthalate (DEHP) เท่านั้น'),(2,'BORTEZOMIB','[\"NSS\"]','คำเตือนการให้ยา','กรณีให้ทาง SC นิยมผสม NSS 1.4 ml (ความเข้มข้นจะเท่ากับ 2.5 mg/ml)'),(3,'CARBOPLATIN','[\"D5W\"]','คำเตือนการให้ยา','ผสม D5W เท่านั้น หากใช้ NSS อาจส่งผลต่อความคงตัวของยา'),(4,'CISPLATIN','[\"D5W\"]','คำเตือนการให้ยา','ผสม NSS เท่านั้น หากผสม D5W โดยไม่มี NSS อาจส่งผลต่อความคงตัวของยา'),(5,'OXALIPLATIN','[\"NSS\"]','คำเตือนการให้ยา','ห้ามผสมใน NSS ให้ผสม D-5-W'),(6,'BENDAMUSTINE','[\"D5W\"]','คำเตือนการให้ยา','ห้ามผสมใน D5W ให้ผสม NSS'),(7,'TRASTUZUMAB','[\"D5W\"]','คำเตือนการให้ยา','ห้ามผสมใน D5W ให้ผสม NSS'),(8,'PEMBROLIZUMAB','[\"NSS\"]','คำเตือนการให้ยา','ต้องใช้ in-line filter (ขนาดรูพรุน 0.2 ถึง 5.0 ไมครอน)'),(9,'ETOPOSIDE','[\"NSS\"]','คำเตือนการให้ยา','ผสม NSS หากความเข้มข้น > 0.4 mg/ml อาจเกิดตะกอนได้'),(10,'IFOSFAMIDE','[\"NSS\"]','คำเตือนการให้ยา','ให้ร่วมกับ MESNA เสมอ');
