INSERT INTO `drugs` VALUES (1,'VINCRISTINE','VINCRISTINE','CHEMOTHERAPY','BSA','ACTUAL',1.40,'mg/m2',2.00,NULL,NULL,1,'2026-06-29 01:42:28',NULL,NULL,0.00,0.00,0.00,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'เล็กน้อย (Mild)','ปลายประสาทอักเสบ, ท้องผูก, ระคายเคืองต่อหลอดเลือด (ยารั่วซึมทำให้เนื้อเยื่อตาย)','เก็บในตู้เย็น (2-8°C) ป้องกันแสง','- CYP3A4 inhibitors (เช่น Itraconazole): เพิ่มพิษต่อระบบประสาท','IV: 1.4 mg/m2 (โดยทั่วไปจะจำกัดขนาดยาสูงสุดที่ 2 mg เพื่อป้องกันพิษต่อระบบประสาท)','ml',NULL,'ml',NULL,NULL,NULL,0,NULL,NULL),(2,'CARBOPLATIN','CARBOPLATIN','CHEMOTHERAPY','CALVERT_FORMULA','ACTUAL',5.00,'Target AUC',1000.00,NULL,125,1,'2026-06-29 01:42:28',NULL,NULL,0.00,0.00,0.00,0,'เจือจางใน D5W หรือ NSS ให้ได้ความเข้มข้น 0.5 - 2 mg/ml',NULL,NULL,NULL,NULL,1,0,NULL,'- ห้ามใช้เข็มหรืออุปกรณ์ที่มีส่วนประกอบของอลูมิเนียม (ยาจะตกตะกอนและเสื่อมสภาพ)\n- กดไขกระดูก (Myelosuppression)','เก็บที่อุณหภูมิห้อง (15-30°C) ป้องกันแสง',NULL,NULL,NULL,NULL,NULL,NULL,'รุนแรง (เกล็ดเลือดต่ำแบบจำกัดขนาดยา)','คลื่นไส้/อาเจียน, ปฏิกิริยาแพ้ยา, พิษต่อไต (น้อยกว่า Cisplatin)','เก็บที่อุณหภูมิ 20-25°C ป้องกันแสง เจือจางใน D5W หรือ NS มีความคงตัว 8 ชั่วโมงที่อุณหภูมิห้อง','- ยาที่เป็นพิษต่อไต (Nephrotoxic drugs): เพิ่มความเสี่ยงต่อความเป็นพิษ','IV: กำหนดเป้าหมาย AUC 4-6 โดยใช้สมการ Calvert (ขนาดยา = AUC x (GFR + 25))','mg',NULL,'ml','[{\"vol\": \"1\", \"dose\": \"50\", \"vol_unit\": \"ml\", \"dose_unit\": \"mg\"}, {\"vol\": \"1\", \"dose\": \"10\", \"vol_unit\": \"ml\", \"dose_unit\": \"mg\"}]',NULL,NULL,0,NULL,NULL),(3,'BLEOMYCIN','BLEOMYCIN','CHEMOTHERAPY','FIXED_DOSE','ACTUAL',30.00,'units',30.00,NULL,NULL,1,'2026-06-29 01:42:28',NULL,NULL,0.00,0.00,0.00,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'เล็กน้อย (พบน้อยที่เป็นแบบจำกัดขนาดยา)','พิษต่อปอด (พังผืด), ไข้, หนาวสั่น, สีผิวคล้ำขึ้น','เก็บในตู้เย็น (2-8°C) ละลายด้วย NS มีความคงตัว 24 ชั่วโมงที่อุณหภูมิห้อง','- ออกซิเจน: การให้ FiO2 สูงระหว่างการผ่าตัดเพิ่มความเสี่ยงต่อพิษต่อปอด\n- Cisplatin: เพิ่มความเสี่ยงต่อพิษต่อปอด','IV/IM/SC: 10-20 units/m2 ทุกสัปดาห์หรือสองครั้งต่อสัปดาห์\nขนาดยาสะสมสูงสุดตลอดชีพ: 400 units (เนื่องจากความเสี่ยงต่อพิษต่อปอด)','mg',NULL,'ml',NULL,NULL,NULL,0,NULL,NULL),(4,'CISPLATIN','CISPLATIN','CHEMOTHERAPY','BSA','ACTUAL',75.00,'mg/m2',200.00,NULL,NULL,1,'2026-06-29 01:42:28',NULL,NULL,0.00,0.00,0.00,0,'เจือจางใน NSS หรือสารละลายที่มี NaCl ≥ 0.2%\n*ห้ามผสมใน D5W ล้วนเด็ดขาด (ยาจะไม่คงตัว)',NULL,NULL,NULL,NULL,1,0,NULL,'- พิษต่อไตสูงมาก (Nephrotoxicity) ต้องทำ Hydration เสมอ\n- คลื่นไส้อาเจียนรุนแรง (High emetogenic)\n- พิษต่อหู (Ototoxicity)','เก็บที่อุณหภูมิห้อง (15-25°C) ห้ามแช่เย็น (จะเกิดผลึก)',NULL,NULL,NULL,NULL,NULL,NULL,'เล็กน้อยถึงปานกลาง (Mild to Moderate)','พิษต่อไต (Nephrotoxicity), คลื่นไส้/อาเจียนรุนแรง, พิษต่อหู (Ototoxicity), ปลายประสาทอักเสบ','เก็บที่อุณหภูมิ 15-25°C ห้ามแช่เย็น (อาจตกตะกอน) เจือจางในสารละลายที่มีคลอไรด์ (เช่น NS)','- Aminoglycosides: เพิ่มความเสี่ยงต่อพิษต่อไตและหู\n- Paclitaxel: บริหารยา Paclitaxel ก่อน','IV: 50-100 mg/m2 ทุก 3-4 สัปดาห์ (ต้องให้น้ำเกลืออย่างเต็มที่ก่อนและหลังให้ยา)','ml',NULL,'ml',NULL,NULL,NULL,0,NULL,NULL),(5,'TRASTUZUMAB','TRASTUZUMAB','TARGETED_THERAPY','WEIGHT_BASED','ACTUAL',6.00,'mg/kg',NULL,NULL,NULL,1,'2026-07-02 07:00:16',NULL,NULL,0.00,0.00,0.00,0,'Reconstitute ด้วย Bacteriostatic Water for Injection (BWFI) หรือ SWFI\nเจือจางต่อด้วย NSS ห้ามใช้ D5W เด็ดขาด',NULL,NULL,NULL,NULL,28,0,NULL,'- ห้ามผสมใน D5W หรือสารละลาย Dextrose\n- ระวังพิษต่อหัวใจ (Cardiotoxicity)\n- ห้ามเขย่าขวดแรงขณะผสมยา (ห้าม shake)','ยาที่ยังไม่ผสมเก็บในตู้เย็น (2-8°C)',NULL,NULL,NULL,NULL,NULL,NULL,'ต้องติดตามอาการอย่างใกล้ชิด (Requires monitoring)','โปรดดูคู่มือยาเฉพาะสำหรับข้อมูลผลข้างเคียงทั้งหมด ที่พบบ่อย: คลื่นไส้, อ่อนเพลีย, เม็ดเลือดต่ำ','ปฏิบัติตามคำแนะนำของผู้ผลิตสำหรับการเก็บรักษา, การละลาย, และการเจือจาง','ปรึกษาเภสัชกรคลินิกหรือฐานข้อมูลปฏิกิริยาระหว่างยาก่อนบริหารยา','ขนาดยาขึ้นอยู่กับสูตรการรักษาเฉพาะทาง โปรดยืนยันกับแพทย์ผู้ทำการรักษา','mg',NULL,'ml',NULL,NULL,NULL,0,NULL,NULL),(6,'PEMBROLIZUMAB','PEMBROLIZUMAB','IMMUNOTHERAPY','FIXED_DOSE','ACTUAL',200.00,'mg',400.00,NULL,NULL,1,'2026-07-02 07:00:16',NULL,NULL,0.00,0.00,0.00,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'ต้องติดตามอาการอย่างใกล้ชิด (Requires monitoring)','โปรดดูคู่มือยาเฉพาะสำหรับข้อมูลผลข้างเคียงทั้งหมด ที่พบบ่อย: คลื่นไส้, อ่อนเพลีย, เม็ดเลือดต่ำ','ปฏิบัติตามคำแนะนำของผู้ผลิตสำหรับการเก็บรักษา, การละลาย, และการเจือจาง','ปรึกษาเภสัชกรคลินิกหรือฐานข้อมูลปฏิกิริยาระหว่างยาก่อนบริหารยา','ขนาดยาขึ้นอยู่กับสูตรการรักษาเฉพาะทาง โปรดยืนยันกับแพทย์ผู้ทำการรักษา','mg',NULL,'ml',NULL,NULL,NULL,0,NULL,NULL),(7,NULL,'DOXORUBICIN','CHEMOTHERAPY','BSA','ACTUAL',60.00,'mg/m2',150.00,NULL,125,1,'2026-07-03 04:14:48',NULL,NULL,0.00,0.00,0.00,0,'Reconstitute ด้วย NSS 5 ml สำหรับยา 10 mg (ความเข้มข้น 2 mg/ml)\n*ห้ามผสมกับ Heparin หรือ 5-FU',NULL,NULL,NULL,NULL,7,0,NULL,'- ยาทำลายเนื้อเยื่ออย่างรุนแรง (Vesicant) ระวังรั่วซึม\n- พิษต่อหัวใจ (Cardiotoxicity)\n- ปัสสาวะอาจมีสีแดง 1-2 วัน','เก็บในตู้เย็น (2-8°C) ป้องกันแสง',NULL,NULL,NULL,NULL,NULL,NULL,'รุนแรง (Severe)','พิษต่อหัวใจ (ขึ้นอยู่กับขนาดยาสะสม), ผมร่วง, ปัสสาวะสีแดง, คลื่นไส้/อาเจียน','เก็บในตู้เย็น (2-8°C) ป้องกันแสง หลังผสมมีความคงตัว 7 วันที่อุณหภูมิห้อง, 15 วันในตู้เย็น','- Trastuzumab: เพิ่มความเสี่ยงต่อพิษต่อหัวใจ\n- Paclitaxel: บริหารยา Doxorubicin ก่อนเพื่อจำกัดความเป็นพิษ','IV: 60-75 mg/m2 ทุก 21 วัน\nขนาดยาสะสมสูงสุด: 450-550 mg/m2 (เนื่องจากพิษต่อหัวใจ)','mg',NULL,'ml','[]',NULL,NULL,0,NULL,NULL),(8,NULL,'CYCLOPHOSPHAMIDE','CHEMOTHERAPY','BSA','ACTUAL',600.00,'mg/m2',NULL,NULL,125,1,'2026-07-03 04:14:48',NULL,NULL,0.00,0.00,0.00,0,'Reconstitute ด้วย NSS\nเจือจางต่อด้วย NSS, D5W, หรือ D5S',NULL,NULL,NULL,NULL,1,0,NULL,'- ระวังกระเพาะปัสสาวะอักเสบและมีเลือดออก (Hemorrhagic cystitis) ต้องดื่มน้ำมากๆ\n- คลื่นไส้อาเจียนปานกลางถึงสูง','เก็บที่อุณหภูมิห้อง (20-25°C) หรือตู้เย็น (2-8°C)',NULL,NULL,NULL,NULL,NULL,NULL,'รุนแรง (เม็ดเลือดขาวต่ำ)','กระเพาะปัสสาวะอักเสบมีเลือดปน (Hemorrhagic cystitis), ผมร่วง, คลื่นไส้/อาเจียน, มะเร็งทุติยภูมิ','เก็บที่อุณหภูมิห้องหรือตู้เย็นขึ้นอยู่กับรูปแบบยา ละลายด้วย NS มีความคงตัว 24 ชั่วโมงที่อุณหภูมิห้อง หรือ 6 วันในตู้เย็น','- Allopurinol: อาจเพิ่มภาวะกดไขกระดูก\n- Doxorubicin: เพิ่มความเสี่ยงต่อพิษต่อหัวใจ','IV: 500-1000 mg/m2 ทุก 3-4 สัปดาห์ (ต้องได้รับน้ำอย่างเพียงพอ; ใช้ Mesna สำหรับยาขนาดสูง)','mg',NULL,'ml',NULL,NULL,NULL,0,NULL,NULL),(9,NULL,'ETOPOSIDE','CHEMOTHERAPY','BSA','ACTUAL',100.00,'mg/m2',NULL,NULL,125,1,'2026-07-03 04:14:48',NULL,NULL,0.00,0.00,0.00,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'ต้องติดตามอาการอย่างใกล้ชิด (Requires monitoring)','โปรดดูคู่มือยาเฉพาะสำหรับข้อมูลผลข้างเคียงทั้งหมด ที่พบบ่อย: คลื่นไส้, อ่อนเพลีย, เม็ดเลือดต่ำ','ปฏิบัติตามคำแนะนำของผู้ผลิตสำหรับการเก็บรักษา, การละลาย, และการเจือจาง','ปรึกษาเภสัชกรคลินิกหรือฐานข้อมูลปฏิกิริยาระหว่างยาก่อนบริหารยา','ขนาดยาขึ้นอยู่กับสูตรการรักษาเฉพาะทาง โปรดยืนยันกับแพทย์ผู้ทำการรักษา','mg',NULL,'ml',NULL,NULL,NULL,0,NULL,NULL),(10,NULL,'DOCETAXEL','CHEMOTHERAPY','BSA','ACTUAL',75.00,'mg/m2',NULL,NULL,125,1,'2026-07-03 04:14:48',NULL,NULL,0.00,0.00,0.00,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'รุนแรง (เม็ดเลือดขาวชนิดนิวโทรฟิลต่ำ)','คั่งน้ำ (Fluid retention), ปฏิกิริยาแพ้ยา, ปลายประสาทอักเสบ, ผมร่วง','เก็บที่อุณหภูมิ 2-25°C ป้องกันแสง ใช้ภาชนะที่ไม่ใช่ PVC','- CYP3A4 inhibitors: อาจเพิ่มระดับยา Docetaxel ในเลือด','IV: 75-100 mg/m2 ทุก 3 สัปดาห์ (ต้องให้คอร์ติโคสเตียรอยด์ก่อนให้ยาเพื่อป้องกันภาวะคั่งน้ำ)','mg',NULL,'ml',NULL,NULL,NULL,0,NULL,NULL),(11,NULL,'5-FU','CHEMOTHERAPY','BSA','ACTUAL',500.00,'mg/m2',NULL,NULL,125,1,'2026-07-03 04:41:02',NULL,NULL,0.00,0.00,0.00,0,'เจือจางใน NSS หรือ D5W',NULL,NULL,NULL,NULL,3,0,NULL,'- ห้ามผสมร่วมกับ Leucovorin ในขวดเดียวกัน (เกิดตะกอน)\n- ระวังแผลในปาก (Stomatitis) และท้องเสีย','เก็บที่อุณหภูมิห้อง (15-25°C) ป้องกันแสง ห้ามแช่เย็น',NULL,NULL,NULL,NULL,NULL,NULL,'ปานกลาง (Moderate)','เยื่อ