INSERT INTO `print_logs` VALUES (1,'00661','พิรัชชัย คนทน','ใบเตรียมยา (Working Formula): 00661','Local Browser','A4',1,'\n        <!DOCTYPE html>\n        <html>\n        <head>\n            <title>ใบบันทึกการเตรียมยาเคมีบำบัด</title>\n            <link href=\"https://fonts.googleapis.com/css2?family=Sarabun:wght@400;700&display=swap\" rel=\"stylesheet\">\n            <style>\n                @page { size: A4; margin: 1cm 1.5cm; }\n                body { \n                    font-family: \'Sarabun\', sans-serif; \n                    margin: 0; \n                    padding: 0;\n                    font-size: 13px;\n                    color: #000;\n                    line-height: 1.6;\n                }\n                .header {\n                    text-align: center;\n                    margin-bottom: 20px;\n                }\n                .header h1 {\n                    font-size: 18px;\n                    margin: 0;\n                    font-weight: bold;\n                }\n                .line-input {\n                    display: inline-block;\n                    border-bottom: 1px solid #000;\n                    padding: 0 5px;\n                    min-height: 16px;\n                }\n                .row {\n                    margin-bottom: 6px;\n                }\n                .checkbox-square {\n                    display: inline-block;\n                    width: 14px;\n                    height: 14px;\n                    border: 1px solid #000;\n                    vertical-align: middle;\n                    margin-right: 4px;\n                    position: relative;\n                    top: -1px;\n                }\n                .lab-row {\n                    display: flex;\n                    align-items: center;\n                    gap: 15px;\n                    margin-bottom: 6px;\n                }\n                .drug-section {\n                    margin-top: 15px;\n                }\n                .drug-block {\n                    margin-bottom: 20px;\n                }\n                .drug-header {\n                    display: flex;\n                    margin-bottom: 4px;\n                    white-space: nowrap;\n                }\n                .qc-section {\n                    margin-top: 5px;\n                }\n                .qc-title {\n                    font-weight: bold;\n                }\n                .qc-grid {\n                    display: grid;\n                    grid-template-columns: auto auto auto;\n                    gap: 5px 20px;\n                    margin-top: 4px;\n                    margin-left: 20px;\n                }\n                .footer {\n                    position: fixed;\n                    bottom: 0;\n                    right: 0;\n                    font-size: 10px;\n                    color: #666;\n                }\n                @media print {\n                    body { -webkit-print-color-adjust: exact; print-color-adjust: exact; }\n                    .footer { position: fixed; bottom: 0; right: 0; }\n                }\n                .text-sm { font-size: 11px; }\n                .text-xs { font-size: 10px; }\n            </style>\n        </head>\n        <body>\n            <div class=\"header\">\n                <h1>ใบบันทึกการเตรียมยาเคมีบำบัด</h1>\n            </div>\n\n            <div class=\"row\">\n                วันที่เตรียมยา <span class=\"line-input\" style=\"width: 150px;\">16 ก.ค. 2569 14:23</span>\n                ผู้เตรียมยา <span class=\"line-input\" style=\"width: 250px;\">admin</span>\n            </div>\n            \n            <div class=\"row\">\n                HN. <span class=\"line-input\" style=\"width: 100px;\">00661</span>\n                ชื่อ-สกุล <span class=\"line-input\" style=\"width: 250px;\">นายพิรัชชัย คนทน</span>\n                อายุ <span class=\"line-input\" style=\"width: 50px; text-align: center;\">30</span> ปี\n                เพศ <span class=\"line-input\" style=\"width: 80px; text-align: center;\">ชาย</span>\n            </div>\n            \n            <div class=\"row\">\n                น้ำหนัก <span class=\"line-input\" style=\"width: 60px; text-align: center;\"></span> kg \n                ส่วนสูง <span class=\"line-input\" style=\"width: 60px; text-align: center;\"></span> cm. \n                BSA = <span class=\"line-input\" style=\"width: 80px; text-align: center;\"></span> m²\n            </div>\n\n\n            <div class=\"drug-section\">\n                <div style=\"font-weight: bold; margin-bottom: 10px;\">Working formula</div>\n                \n                <div class=\"drug-block\">\n                    <div style=\"display: flex; flex-wrap: wrap; align-items: flex-end; margin-bottom: 6px;\">\n                        <div style=\"width: 20px;\">1.</div>\n                        <div>Drug</div>\n                        <div class=\"line-input\" style=\"width: 180px; margin: 0 10px 0 5px;\">CISPLATIN</div>\n                        <div>Dose formular</div>\n                        <div class=\"line-input\" style=\"flex: 1; min-width: 150px; margin: 0 10px 0 5px;\">2.00 m2 x 75 mg/m2</div>\n                        <div>Dose</div>\n                        <div class=\"line-input\" style=\"width: 90px; text-align: center; margin-left: 5px;\">150 mg</div>\n                    </div>\n                    <div style=\"display: flex; align-items: flex-start; margin-left: 20px; margin-bottom: 6px;\">\n                        <div style=\"white-space: nowrap; margin-right: 5px; margin-top: 2px;\">สารละลายและปริมาตรที่ใช้ละลายผงยา (Reconstitution)</div>\n                        <div class=\"line-input\" style=\"flex: 1; text-align: left; line-height: 1.5;\">เจือจางใน NSS หรือสารละลายที่มี NaCl ≥ 0.2%\n*ห้ามผสมใน D5W ล้วนเด็ดขาด (ยาจะไม่คงตัว)</div>\n                    </div>\n                    <div style=\"display: flex; align-items: flex-end; margin-left: 20px; margin-bottom: 6px;\">\n                        <div style=\"white-space: nowrap; margin-right: 5px;\">ปริมาตรยาที่เตรียม</div>\n                        <div class=\"line-input\" style=\"width: 70px; text-align: center; font-weight: bold;\">150</div>\n                        <div style=\"white-space: nowrap; margin-left: 5px;\">ml (ใช้ 3 ขวด)</div>\n                        <div style=\"white-space: nowrap; margin-left: 10px; margin-right: 5px;\">(Add ลงใน Diluent</div>\n                        <div class=\"line-input\" style=\"flex: 1;\">NSS</div>\n                        <div style=\"white-space: nowrap; margin-left: 5px; margin-right: 5px;\">ปริมาตร</div>\n                        <div class=\"line-input\" style=\"width: 50px; text-align: center;\">30</div>\n                        <div style=\"white-space: nowrap; margin-left: 5px;\">ml)</div>\n                    </div>\n                    <div class=\"qc-section\" style=\"margin-left: 20px;\">\n                        <div class=\"qc-title\">การตรวจสอบคุณภาพยาเคมีบำบัดที่ผสมเสร็จ</div>\n                        <div class=\"qc-grid\">\n                            <div><span class=\"checkbox-square\"></span> เตรียมยาและสารน้ำถูกชนิด</div>\n                            <div><span class=\"checkbox-square\"></span> เตรียมยาถูกขนาด</div>\n                            <div><span class=\"checkbox-square\"></span> ปราศจากตะกอนหรือฝุ่นผง</div>\n                            \n                            <div><span class=\"checkbox-square\"></span> ภาชนะบรรจุยาไม่รั่วซึม</div>\n                            <div><span class=\"checkbox-square\"></span> ติดฉลากถูกต้อง</div>\n                            <div>เภสัชกรผู้ตรวจสอบ <span class=\"line-input\" style=\"width: 150px;\"></span></div>\n                        </div>\n                    </div>\n                </div>\n            \n            </div>\n\n            <div class=\"footer\">FMMU-0007-00</div>\n        </body>\n        </html>\n        ','0000','2026-07-16 07:23:42','2026-07-16 07:23:42'),(2,'00661','พิ